{"implementation":"def solve(case):
    nodes = case['nodes']
    threshold = case['utility_threshold']
    children = {}
    node_map = {}
    for node in nodes:
        nid = node['id']
        node_map[nid] = node
        children[nid] = []
    root_id = None
    for node in nodes:
        if node['parent'] is None:
            root_id = node['id']
        else:
            children[node['parent']].append(node['id'])
    result_ids = []
    def dfs(nid):
        node = node_map[nid]
        retain = (node['utility'] >= threshold) or (not node['removable'])
        if not retain:
            return
        result_ids.append(nid)
        for child in children.get(nid, []):
            dfs(child)
    dfs(root_id)
    return {'retained_node_ids': result_ids, 'visit_order': result_ids}"}
